insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'conclusion',1,'Seven indexed records (Bukhārī 2, Muslim 3, Nasāʾī 1, Tirmidhī 1) all go back to Ibn ʿUmar alone, through five different successors: ʿIkrima b. Khālid, Nāfiʿ, Saʿd b. ʿUbayda, Muḥammad b. Zayd and Ḥabīb b. Abī Thābit. The report is single-companion but multi-successor.',array['bukhari:8','bukhari:4513','muslim:16a','muslim:16c','tirmidhi:2609']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'conclusion',2,'The first pillar is worded in four ways: "testimony that there is no god but Allah" (Bukhārī 8, Muslim 16c, Nasāʾī 5001, Tirmidhī 2609), "that Allah be declared One" (Muslim 16a), "that Allah be worshipped and what is besides Him disbelieved in" (Muslim 16b) and "belief in Allah and His Messenger" (Bukhārī 4513). These are wording variants of the same pillar.',array['bukhari:8','muslim:16a','muslim:16b','bukhari:4513']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'conclusion',3,'The order of fasting and ḥajj differs. Ḥajj comes before fasting in Bukhārī 8, Muslim 16b and 16c, and Nasāʾī 5001; fasting comes first in Muslim 16a, Bukhārī 4513 and Tirmidhī 2609. The engine labels this an apparent contradiction on order only, since all seven list the same five pillars.',array['bukhari:8','muslim:16b','nasai:5001','muslim:16a','tirmidhi:2609']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'conclusion',4,'In Muslim 16a (Saʿd b. ʿUbayda route), a listener repeats the list as "ḥajj and fasting Ramaḍān" and Ibn ʿUmar corrects him: "No: fasting Ramaḍān and ḥajj. This is how I heard it from the Messenger of Allah." Other routes of the same companion give ḥajj first, so the order varied in transmission below Ibn ʿUmar (candidate reading).',array['muslim:16a','muslim:16b','bukhari:8']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'conclusion',5,'Bukhārī 4513 and Nasāʾī 5001 quote the hadith inside a story: men urge Ibn ʿUmar to fight during civil strife, and he answers with the five pillars. These are complementary context, not a different statement.',array['bukhari:4513','nasai:5001']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'uncertainty',1,'How classical commentators reconcile the two orders was not source-checked here. The engine only records that both orders are transmitted.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='islam-built-on-five'),'uncertainty',2,'Copies in 40 Nawawī, Riyāḍ al-Ṣāliḥīn, Mishkāt and the Shīʿī collections held in the corpus are out of scope for this pilot.','grok-bot') on conflict do nothing;
